import { test, expect } from '@playwright/test';

test.describe('Clear All Filters Button', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should clear all applied filters with a single button click', async ({ page }) => {
    // Apply multiple filters
    const categoryFilter = page.getByRole('button', { name: /category/i });
    await categoryFilter.click();
    const categorySelect = page.getByRole('combobox', { name: /category/i });
    await categorySelect.fill('books');

    const priceFilter = page.getByRole('button', { name: /price/i });
    await priceFilter.click();
    const priceRangeSelect = page.getByRole('combobox', { name: /price/i });
    await priceRangeSelect.fill('under $10');

    const authorFilter = page.getByRole('button', { name: /author/i });
    await authorFilter.click();
    const authorSelect = page.getByRole('combobox', { name: /author/i });
    await authorSelect.fill('J.K. Rowling');

    // Verify filters are applied
    const resultsList = page.getByRole('list', { name: /search results/i });
    await expect(resultsList).toBeVisible();

    // Click clear button
    const clearButton = page.getByRole('button', { name: /clear filters/i });
    await clearButton.click();

    // Verify filters are cleared
    await expect(categorySelect).toBeEmpty();
    await expect(priceRangeSelect).toBeEmpty();
    await expect(authorSelect).toBeEmpty();

    // Verify results list is empty
    await expect(resultsList).toHaveCount(0);

    // Verify clear button is disabled after clearing
    await expect(clearButton).toBeDisabled();
  });

  test('should handle clear button click when no filters are applied', async ({ page }) => {
    // Verify results list is empty initially
    const resultsList = page.getByRole('list', { name: /search results/i });
    await expect(resultsList).toHaveCount(0);

    // Click clear button
    const clearButton = page.getByRole('button', { name: /clear filters/i });
    await clearButton.click();

    // Verify results list is still empty
    await expect(resultsList).toHaveCount(0);

    // Verify clear button is enabled
    await expect(clearButton).not.toBeDisabled();
  });
});
